/**
 * Optimizer with the following tasks:
 *
 * 1. Group {@link ExclusiveStatement} into {@link ExclusiveGroup} 2. Adjust the join order using
 * {@link DefaultFedXCostModel}
 *
 *
 * @author as
 */
public class StatementGroupAndJoinOptimizer extends AbstractSimpleQueryModelVisitor<OptimizationException>
		implements FedXOptimizer {

	private static final Logger log = LoggerFactory.getLogger(StatementGroupAndJoinOptimizer.class);

	protected final QueryInfo queryInfo;

	private final FedXCostModel costModel;

	public StatementGroupAndJoinOptimizer(QueryInfo queryInfo, FedXCostModel costModel) {
		super(true);
		this.queryInfo = queryInfo;
		this.costModel = costModel;
	}

	@Override
	public void optimize(TupleExpr tupleExpr) {
		tupleExpr.visit(this);
	}

	@Override
	public void meet(Service tupleExpr) {
		// stop traversal
	}

	@Override
	public void meetOther(QueryModelNode node) {
		if (node instanceof NJoin) {
			super.meetOther(node); // depth first
			meetNJoin((NJoin) node);
		} else {
			super.meetOther(node);
		}
	}

	protected void meetNJoin(NJoin node) {

		List<TupleExpr> args = node.getArgs();

		args = fuseRelationalGraphOperands(args);

		// form groups
		args = formGroups(args);

		if (args.isEmpty()) {
			OptimizerUtil.replaceNJoinPreservingScope(node, new EmptyNJoin(node, queryInfo));
			return;
		}

		// if the join args could be reduced to just one, e.g. ExclusiveGroup
		// we can safely replace the join node
		if (args.size() == 1) {
			log.debug("Join arguments could be reduced to a single argument, replacing join node.");
			OptimizerUtil.replaceNJoinPreservingScope(node, args.get(0));
			return;
		}

		// optimize the join order
		args = optimizeJoinOrder(args);

		// exchange the node
		NJoin newNode = new NJoin(args, queryInfo);
		OptimizerUtil.replaceNJoinPreservingScope(node, newNode);
	}

	/**
	 * Keep a lowered GRAPH and other pure patterns at the same endpoint in one remote relational join. The GRAPH
	 * boundary is consumed only for this atomic group: its named-context patterns and every other participant must
	 * admit the same compatible-binding join, with no FedX annotations that require separate evaluation.
	 */
	private List<TupleExpr> fuseRelationalGraphOperands(List<TupleExpr> args) {
		boolean hasGraphBoundary = args.stream()
				.anyMatch(arg -> arg instanceof Extension extension && extension.isGraphScopeBoundary());
		if (!hasGraphBoundary) {
			return args;
		}

		List<TupleExpr> result = new ArrayList<>(args);
		Set<String> precedingNames = new HashSet<>();
		boolean precedingKnown = true;
		boolean changed = false;
		RelationalGraphGroup current = null;
		for (int index = 0; index < args.size(); index++) {
			TupleExpr arg = args.get(index);
			boolean graphBoundary = arg instanceof Extension extension && extension.isGraphScopeBoundary()
					&& extension.getElements().isEmpty();
			TupleExpr operand = graphBoundary ? ((Extension) arg).getArg() : arg;
			ExclusiveTupleExpr exclusive = operand instanceof ExclusiveTupleExpr candidate ? candidate : null;
			StatementSource owner = exclusive == null ? null : exclusive.getOwner();
			List<ExclusiveTupleExpr> flattened = new ArrayList<>();
			List<StatementPattern> statements = new ArrayList<>();
			boolean safe = owner != null && collectRelationalStatements(exclusive, owner, flattened, statements);
			if (!safe || current != null && !current.owner.equals(owner)) {
				if (current != null) {
					changed |= finishRelationalGraphGroup(current, result, precedingNames, precedingKnown);
					precedingNames.addAll(current.outputNames);
					precedingKnown &= current.outputsKnown;
					current = null;
				}
			}
			if (!safe) {
				EndpointGroupSafety.OutputNames output = EndpointGroupSafety.outputNames(arg);
				precedingNames.addAll(output.names());
				precedingKnown &= output.known();
				continue;
			}
			if (current == null) {
				current = new RelationalGraphGroup(owner);
			}
			current.positions.add(index);
			current.parts.add(new RelationalPart(exclusive, graphBoundary, flattened));
			current.statements.addAll(statements);
			current.hasGraphBoundary |= graphBoundary;
			EndpointGroupSafety.OutputNames output = EndpointGroupSafety.outputNames(operand);
			current.outputNames.addAll(output.names());
			current.outputsKnown &= output.known();
		}
		if (current != null) {
			changed |= finishRelationalGraphGroup(current, result, precedingNames, precedingKnown);
		}
		if (!changed) {
			return args;
		}
		result.removeIf(Objects::isNull);
		return result;
	}

	private boolean finishRelationalGraphGroup(RelationalGraphGroup candidate, List<TupleExpr> result,
			Set<String> precedingNames, boolean precedingKnown) {
		if (!candidate.hasGraphBoundary || candidate.positions.size() < 2
				|| !permitsRelationalFusion(candidate.statements)) {
			return false;
		}
		List<EndpointGroupSafety.Operand> proofOperands = new ArrayList<>(candidate.parts.size());
		for (RelationalPart part : candidate.parts) {
			proofOperands.add(new EndpointGroupSafety.Operand(part.expression(), part.graphBoundary()));
		}
		EndpointGroupSafety.Proof proof = EndpointGroupSafety.capture(proofOperands);
		if (!proof.safeOuterInjection(precedingNames, precedingKnown)) {
			return false;
		}
		List<ExclusiveTupleExpr> operands = new ArrayList<>();
		for (RelationalPart part : candidate.parts) {
			if (part.graphBoundary()) {
				ExclusiveGroup boundary = new ExclusiveGroup(List.of(part.expression()), candidate.owner, queryInfo);
				boundary.setVariableScopeChange(true);
				operands.add(boundary);
			} else {
				operands.addAll(part.flattened());
			}
		}
		result.set(candidate.positions.get(0), new ExclusiveGroup(operands, candidate.owner, queryInfo));
		for (int i = 1; i < candidate.positions.size(); i++) {
			result.set(candidate.positions.get(i), null);
		}
		return true;
	}

	private boolean collectRelationalStatements(ExclusiveTupleExpr expression, StatementSource owner,
			List<ExclusiveTupleExpr> operands, List<StatementPattern> statements) {
		List<ExclusiveTupleExpr> leaves = new ArrayList<>();
		boolean retainBoundary = false;
		Deque<ExclusiveTupleExpr> pending = new ArrayDeque<>();
		Set<ExclusiveGroup> seenGroups = Collections.newSetFromMap(new IdentityHashMap<>());
		pending.push(expression);
		while (!pending.isEmpty()) {
			ExclusiveTupleExpr current = pending.pop();
			if (!owner.equals(current.getOwner())) {
				return false;
			}
			QueryRef ref = current;
			if (ref.getQueryInfo() != queryInfo || ref.getExecutionDataset() != queryInfo.getDataset()
					|| ref.getResolvedGraphSelection() != null) {
				return false;
			}
			if (current instanceof FilterTuple filter) {
				if (filter.getBoundFilters() != null
						|| filter.getFilterExpr() != null && !FilterUtils.canRender(filter.getFilterExpr())) {
					return false;
				}
				retainBoundary |= filter.getFilterExpr() != null;
			}
			retainBoundary |= current instanceof VariableScopeChange boundary && boundary.isVariableScopeChange();
			if (current.getClass() == ExclusiveStatement.class) {
				ExclusiveStatement statement = (ExclusiveStatement) current;
				if (!BindingScopePolicy.isRelationalBindingLeaf(statement) || statement.getSourceCount() != 1
						|| statement.getUpperLimit() > 0) {
					return false;
				}
				leaves.add(statement);
				statements.add(new StatementPattern(statement.getScope(), statement.getSubjectVar().clone(),
						statement.getPredicateVar().clone(), statement.getObjectVar().clone(),
						statement.getContextVar() == null ? null : statement.getContextVar().clone()));
			} else if (current.getClass() == ExclusiveGroup.class) {
				ExclusiveGroup group = (ExclusiveGroup) current;
				if (!seenGroups.add(group) || group.getExclusiveExpressions().isEmpty()) {
					return false;
				}
				List<ExclusiveTupleExpr> children = group.getExclusiveExpressions();
				for (int i = children.size() - 1; i >= 0; i--) {
					pending.push(children.get(i));
				}
			} else {
				return false;
			}
		}
		if (retainBoundary) {
			operands.add(expression);
		} else {
			operands.addAll(leaves);
		}
		return true;
	}

	private static boolean permitsRelationalFusion(List<StatementPattern> statements) {
		Set<String> names = new HashSet<>();
		statements.forEach(statement -> names.addAll(statement.getBindingNames()));
		for (StatementPattern statement : statements) {
			if (!QueryEvaluationUtility.permitsBindingInjection(statement, names)) {
				return false;
			}
		}
		return true;
	}

	private static final class RelationalGraphGroup {
		private final StatementSource owner;
		private final List<Integer> positions = new ArrayList<>();
		private final List<RelationalPart> parts = new ArrayList<>();
		private final List<StatementPattern> statements = new ArrayList<>();
		private final Set<String> outputNames = new HashSet<>();
		private boolean hasGraphBoundary;
		private boolean outputsKnown = true;

		private RelationalGraphGroup(StatementSource owner) {
			this.owner = owner;
		}
	}

	private record RelationalPart(ExclusiveTupleExpr expression, boolean graphBoundary,
			List<ExclusiveTupleExpr> flattened) {
	}

	/**
	 * Group {@link ExclusiveStatement}s having the same source into an {@link ExclusiveGroup}.
	 *
	 * @param originalArgs
	 * @return the new (potentially grouped) join arguments. If empty, the join will not produce any results.
	 */
	protected List<TupleExpr> formGroups(List<TupleExpr> originalArgs) {

		LinkedList<TupleExpr> newArgs = new LinkedList<>();
		Map<ExclusiveTupleExpr, Boolean> groupable = new IdentityHashMap<>();
		for (TupleExpr arg : originalArgs) {
			if (arg instanceof ExclusiveTupleExpr exclusive) {
				groupable.put(exclusive, OptimizerUtil.preservesGroupingContract(exclusive, queryInfo));
			}
		}

		LinkedList<TupleExpr> argsCopy = new LinkedList<>(originalArgs);
		while (!argsCopy.isEmpty()) {

			TupleExpr t = argsCopy.removeFirst();

			/*
			 * If one of the join arguments cannot produce results, the whole join expression does not produce results.
			 * => return an null as marker to replace with empty join
			 */
			if (t instanceof EmptyResult) {
				return Collections.emptyList();
			} else if (t instanceof ExclusiveTupleExpr exclusive && !Boolean.TRUE.equals(groupable.get(exclusive))) {
				newArgs.add(t);
			}

			/*
			 * for (existing) exclusive groups (e.g. created by SERVICE clauses) add potential ExclusiveTupleExpr with
			 * the same source to the group
			 */
			else if (t instanceof ExclusiveGroup) {

				ExclusiveGroup current = (ExclusiveGroup) t;

				List<ExclusiveTupleExpr> l = null;
				for (TupleExpr te : argsCopy) {

					/*
					 * in the remaining join args find exclusive statements / expressions having the same source, and
					 * add to a list which is later used to form an exclusive group
					 */
					if (te instanceof ExclusiveTupleExpr) {
						ExclusiveTupleExpr check = (ExclusiveTupleExpr) te;
						if (Boolean.TRUE.equals(groupable.get(check)) && check.getOwner().equals(current.getOwner())) {
							if (l == null) {
								l = new ArrayList<>();
								l.addAll(current.getExclusiveExpressions());
							}
							if (check instanceof ExclusiveGroup) {
								l.addAll((((ExclusiveGroup) check).getExclusiveExpressions()));
							} else {
								l.add(check);
							}
						}
					}
				}

				// check if we have a modification, otherwise add existing node
				if (l != null) {
					argsCopy.removeAll(l);
					argsCopy.remove(current);
					newArgs.add(new ExclusiveGroup(l, current.getOwner(), queryInfo));
				} else {
					newArgs.add(current);
				}

			}

			/*
			 * for exclusive statements find those belonging to the same source (if any) and form exclusive group
			 */
			else if (t instanceof ExclusiveTupleExpr) {
				ExclusiveTupleExpr current = (ExclusiveTupleExpr) t;

				List<ExclusiveTupleExpr> l = null;
				List<ExclusiveGroup> toRemoveFromArgs = null; // contains exclusive groups have to be removed
				for (TupleExpr te : argsCopy) {
					/*
					 * scan for exclusive groups having the same owner and flatten
					 */
					if (te instanceof ExclusiveGroup) {
						ExclusiveGroup check = (ExclusiveGroup) te;
						if (Boolean.TRUE.equals(groupable.get(check)) && check.getOwner().equals(current.getOwner())) {
							if (l == null) {
								l = new ArrayList<>();
								l.add(current);
							}
							if (toRemoveFromArgs == null) {
								toRemoveFromArgs = new ArrayList<>();
							}
							toRemoveFromArgs.add(check);
							l.addAll(check.getExclusiveExpressions());
						}
					}

					/*
					 * in the remaining join args find exclusive expressions‚ having the same source, and add to a list
					 * which is later used to form an exclusive group
					 */
					else if (te instanceof ExclusiveTupleExpr) {
						ExclusiveTupleExpr check = (ExclusiveTupleExpr) te;
						if (Boolean.TRUE.equals(groupable.get(check)) && check.getOwner().equals(current.getOwner())) {
							if (l == null) {
								l = new ArrayList<>();
								l.add(current);
							}
							l.add(check);
						}
					}

				}

				// check if we can construct a group, otherwise add directly
				if (l != null) {
					argsCopy.removeAll(l);
					if (toRemoveFromArgs != null) {
						argsCopy.removeAll(toRemoveFromArgs);
					}
					newArgs.add(new ExclusiveGroup(l, current.getOwner(), queryInfo));
				} else {
					newArgs.add(current);
				}
			} else {
				newArgs.add(t);
			}
		}

		return newArgs;
	}

	/**
	 * Join Order Optimizer
	 *
	 * Group -> Statements according to number of free Variables
	 *
	 * Additional Heuristics: - ExclusiveGroups are cheaper than any other subquery - owned statements are cheaper if
	 * they have a single free variable
	 *
	 * @param joinArgs
	 * @return
	 */
	protected List<TupleExpr> optimizeJoinOrder(List<TupleExpr> joinArgs) {

		List<TupleExpr> optimized = new ArrayList<>(joinArgs.size());
		List<TupleExpr> left = new LinkedList<>(joinArgs);
		Set<String> joinVars = new HashSet<>();

		while (!left.isEmpty()) {

			TupleExpr item = left.get(0);

			double minCost = Double.MAX_VALUE;
			for (TupleExpr tmp : left) {

				double currentCost = estimateCost(tmp, joinVars);
				if (currentCost < minCost) {
					item = tmp;
					minCost = currentCost;
				}
			}

			joinVars.addAll(QueryAlgebraUtil.getFreeVars(item));
			if (log.isTraceEnabled()) {
				log.trace("Cost of " + item.getClass().getSimpleName() + " is determined as " + minCost);
			}
			optimized.add(item);
			left.remove(item);
		}

		return optimized;
	}

	protected double estimateCost(TupleExpr tupleExpr, Set<String> joinVars) {
		return costModel.estimateCost(tupleExpr, joinVars);
	}
}
